<?php
declare(strict_types=1); namespace App\Http\Controllers\TeachingAssignments; use App\Http\Controllers\Controller;use App\Models\{TeachingAssignmentSet,TeachingImportBatch};use App\Services\TeachingAssignments\TeachingAssignmentSetService;use Illuminate\Http\{RedirectResponse,Request};
class TeachingAssignmentSetController extends Controller {public function confirmImport(Request $r,TeachingImportBatch $batch,TeachingAssignmentSetService $s):RedirectResponse{abort_unless($r->user()->can('teaching-assignments.create'),403);$set=$s->fromImport($batch,$r->user());return redirect()->route('teaching-assignments.index',['set'=>$set->id,'tab'=>'inspection'])->with('success','Hasil import disimpan sebagai draft dan belum aktif.');} public function rebuild(Request $r,TeachingAssignmentSet $set,TeachingAssignmentSetService $s):RedirectResponse{abort_unless($r->user()->can('teaching-assignments.create'),403);$s->rebuild($set,$r->user());return redirect()->route('teaching-assignments.index',['set'=>$set->id,'tab'=>'inspection'])->with('success','Draft berhasil dibangun ulang. 117 Struktur JP dan penugasan dari XLSX telah disinkronkan.');}}
